  "1151": {"q":"{旅先|たびさき}で{入|はい}った{店|みせ}で、（　　）{高校時代|こうこうじだい}の{同級生|どうきゅうせい}に{会|あ}った。","options":["万一","本来","偶然","元々"],"answer":2,"vi":"Ở cửa hàng ghé vào trong chuyến đi, tôi tình cờ gặp bạn cùng lớp thời cấp ba.","explain":"偶然: tình cờ. 万一: lỡ như; 本来: vốn dĩ; 元々: ban đầu."},
  "1152": {"q":"{昨日|きのう}は（　　）{早|はや}く{起|お}きたので、{朝日|あさひ}を{見|み}ることができた。","options":["万一","たまたま","本来","同様"],"answer":1,"vi":"Hôm qua tình cờ dậy sớm nên tôi được ngắm mặt trời mọc.","explain":"たまたま: tình cờ. 万一: lỡ như; 本来: vốn dĩ; 同様: giống như."},
  "1153": {"q":"{話|はなし}で{聞|き}くのと、（　　）にやってみるのとでは{大違|おおちが}いだ。","options":["実際","同様","元々","本来"],"answer":0,"vi":"Nghe kể và thực tế làm thử là khác nhau hoàn toàn.","explain":"実際に: trên thực tế. 本来: vốn dĩ; 同様に: tương tự; 元々: ban đầu."},
  "1154": {"q":"この{新製品|しんせいひん}は、{従来|じゅうらい}の{製品|せいひん}と（　　）の{方法|ほうほう}で{使|つか}うことができる。","options":["実際","元々","本来","同様"],"answer":3,"vi":"Sản phẩm mới này có thể sử dụng theo cách giống như sản phẩm cũ.","explain":"〜と同様: giống như. 実際: thực tế; 本来: vốn dĩ; 元々: ban đầu."},
